export function augmentCurriculum(tracks:Track[]){
 for(const [i, rows] of Object.entries(additions)) tracks[Number(i)].questions.push(...rows.map(question));
 tracks[3].title="Laravel Architecture & Lifecycle";
 tracks[3].desc="Lifecycle، Container، Providers، Config، وFacades";
 for(const m of modules) tracks.push({...m,questions:[...m.rows,...(extraRows[m.title]||[])].map(question)});
}
export function trackGroup(i:number):string {return i>=38?"Feature Design":i>=26?"Engineering":i===0||i===1||i===2?"PHP":i===3?"Laravel":i===9?"AI":i<10?"Backend":modules[i-10]?.group||"Backend"}
